public class NativeSyncBridge {
    private final Object intrinsicLock = new Object();

    // Native method declaration
    public native void processNativeData(byte[] data);

    // Thread-safe wrapper using an intrinsic lock around a JNI call
    public void safeExecute(byte[] data) {
        synchronized (intrinsicLock) {
            // Warning: Holding JVM intrinsic locks during long JNI calls can block other threads
            processNativeData(data);
        }
    }

    static {
        System.loadLibrary("native-core");
    }
}
